def _table_exists(insp, name: str) -> bool:
    try:
        return name in set(insp.get_table_names())
    except Exception:  # noqa: BLE001
        return False


def _columns(insp, table: str) -> set[str]:
    try:
        return {c["name"] for c in insp.get_columns(table)}
    except Exception:  # noqa: BLE001
        return set()


