function add(n,title,criterion,keys,steps,expected,negative,fe,be,db,ux,native,extra=[]){controls.push({id:`A02.C${String(n).padStart(3,'0')}`,title,criterion_atomic:criterion,requirement_ids:[],task_ids:[],task_binding:'A12 va lega taskul canonic P01.Cxx.Txxxx, păstrând codul original/aliasul; lipsa taskului este cerință fără task, nu inventare de coduri',source_candidates:refs(...keys),steps,expected,negative_cases:negative,evidence_by_layer:{frontend:fe,backend:be,db,ux,native},prerequisites:[...commonPrereq,...extra],probe_type:['inspecție statică după gate','SELECT în snapshot autorizat','integrare/UX numai în cabinet efemer dacă sunt efecte'],fixture:'A02_FIXTURE_CORE_V1, ajustată cu datele specifice controlului și capturată înainte/după',cleanup:'Revocare credențiale fixture și eliminare exclusiv a cabinetului efemer verificat de A10 după exportul dovezilor; niciun DELETE de audit în producție.',owner:'A02',independent_reviewer:'A11',status:'NEEXECUTAT',actual_result:null,evidence_ids:[],finding_ids:[]});}
add(1,'Baseline schemă instalată','Fiecare observație DB poate fi atribuită unei versiuni instalate și unui cabinet exact.',['activator','metadata','clientmap'],['Captură Git SHA/tree și hash surse; colectare manifest bundle/build/deploy prin A10.','SELECT versiune PostgreSQL, schemă și istoricul migrărilor disponibil; înregistrare explicită a lipsei istoricului.','Compară fără extrapolare baseline repo cu baseline instalat; stabilește ce variantă va fi auditată.'],['Versiunile Git/core/plugins/schema/deploy au identități distincte, dată și proveniență.'],['Bundle mai vechi decât Git; două cabinete cu scheme diferite; migrare fără jurnal.'],'Captură footer/despre și context cabinet, fără date personale.','Manifest artefact cu SHA/build; log de startup redactat.','SQL01 + inventar schema_version dacă există, fără a inventa tabela.','Auditorul poate identifica mediul și versiunea din probă.','Source bundle core iDempiere exact instalat și dovadă matching de versiune.');
add(2,'Inventar închis AD–schemă','Fiecare tabel/coloană din suprafața A02 are sursă, proprietar și corespondență explicită cu AD și schema fizică.',['metadata','coretables','fluxtables','wmsmodel','productsql'],['Enumeră toate definițiile și utilizările din corpus fixat, inclusiv SQL din șiruri Java/Python.','Extrage prin SELECT metadate fizice și AD; full outer join offline pe nume normalizat, nu numai intersecția.','Clasifică lipsă AD, lipsă fizic, câmp retras păstrat fizic, nativ, EVA, extensie portal și tabel runtime-only.'],['Numitorul total și fiecare diferență au dispoziție; 0 obiecte neatribuite acceptate tacit.'],['Coloană fizică veche EVA_GestiuniStoc; nume diferit doar la case; tabel plugin absent; coloană AD fără fizic.'],'Ecran System/Dictionary cu rol audit dacă accesibil.','Manifest surse→obiecte cu linie/simbol.','SQL02/03; export doar metadate.','Câmpurile retrase nu rămân editabile prin ecrane/cache vechi.','Separă AD EntityType=EVA de core; confirmă politica de extensie în core fixat.');
add(3,'Tip și nulabilitate','Fiecare câmp persistent acceptă exact domeniul de valori definit în AD și contractul de business.',['metadata','wmsmodel','productnew','productsql'],['Compară tip/lungime/precizie/default/nullability și IsMandatory/Reference/IsEncrypted.','Aplică limite pe produs Value/Name, Qty, sume, date, texte Unicode în fixture prin UI și API.','Verifică citirea valorii persistate și mesajul erorii; examinează transformări tăcute.'],['Fără truncare, conversie pierdută sau NULL care schimbă sensul; regulile server coincid cu UI.'],['Valoare de lungime maxim+1; Qty cu precizie suplimentară; gol vs NULL; diacritice; decimale virgulă.'],'Capturi formular produs și set WMS la limită.','Parametri validați și excepție controlată în layer de persistare.','SQL02/03 plus SELECT rânduri fixture pe ID.','Mesaj spune câmpul și limita; datele introduse rămân pentru corectare.','Verifică DisplayType/MColumn/PO pentru versiunea core reală.');
add(4,'Chei și referințe tenant','O referință persistentă nu poate conecta date între firme/cabinete neautorizate.',['warehouseaccess','clientmap','wmsmodel','productmatch'],['Inventariază FK reale și referințe logice, inclusiv coloane Record_ID/AD_Table_ID.','Construiește două cabinete și două AD_Client cu ID numeric repetat în DB separate; urmărește rezolvarea.','Trimite în test ID al altei firme pe API/proces și compară starea înainte/după.'],['Refuz server; zero rânduri în alt context; referințele permise la AD_Client=0 explicate explicit.'],['Locator al altei firme; canal cu ID ghicit; managed firm același CUI în două cabinete.'],'Context firmă/gestiune clar și captură refuz.','Rezoluție managing_uuid+tenant și filtrare server.','SQL04/05; queryuri orphan cu parametri client; registru FK reale/logice.','Schimbarea firmei golește selecțiile incompatibile și păstrează contextul vizibil.','AD_Client/AD_Org/AccessLevel și referințele sistem verificate cu A01.');
add(5,'Identități CPP/CPA distincte','Produsul primar și forma asamblată comercială au identități interne diferite chiar când denumirea este identică.',['productnew','productevents','productform','productmap','productmodels'],['Definește fixture P1_CPP, P1_CPA cu rețetă 1 P1_CPP+cutie+0,5h și S1_CPP/S1_CPA dacă se cumpără și se asamblează.','Urmărește create/import/mapare/BOM și cheile tuturor referințelor.','Schimbă SKU/EAN/nume fără a schimba identitatea; verifică selecția în comandă, pick și facturare.'],['ID intern distinct CPP/CPA; legătura de conversie explicită/versionată; niciun merge pe nume/EAN.'],['EAN comun; nume identic; import repetat; mapare automată ambiguă.'],'Capturi catalog cu cod intern și tip catalog vizibile.','MProduct/serviciu/mapare produc două identități și resping asocierea ambiguă.','SELECT M_Product, tabela relației descoperită și BOM; ID/UUID/Value distinct documentate.','Utilizatorul distinge imediat CPP de CPA; nu este obligat să interpreteze SKU.','Nu presupune că Value/UUID/M_Product_ID nativ rezolvă separat toate cerințele; dovadă pe versiune.');
add(6,'Identitate permanentă fără reutilizare','Un identificator intern alocat nu este reutilizat pentru alt produs după cicluri de viață și restaurare.',['productnew','productevents','productmodels','sagaproduct'],['Stabilește domeniul explicit al identificatorului: DB/cabinet/firme plus format global dacă cerința îl cere.','Testează dezactivare, ștergere autorizată în fixture, recreare, import și restore vechi cu alocări ulterioare.','Verifică registru/tombstone/UUID/namespace sau mecanism existent echivalent și reconciliere cu canale.'],['Nicio coliziune în domeniul declarat; niciun ID vechi nu identifică alt produs după restore; lipsa garanției se raportează.'],['Restore snapshot anterior alocării; reset secvență; clone cabinet; UUID importat duplicat; cod reciclat.'],'Căutare după cod vechi arată produsul original/inactiv, nu altul.','Trace allocator și import; metodă de recuperare namespace.','SELECT AD_Sequence, PK/UUID/unique și registrul identităților dacă există; nu se propune registru nou înainte de analiza nativă.','Dezactivarea avertizează consecințele și păstrează istoricul.','Dublă verificare core MSequence/PO/UUID și efect instalat; native-only neverreuse nu se declară implicit.');
add(7,'Unicitate concurentă a codurilor','Două alocări concurente nu produc aceeași identitate/cod în domeniul de unicitate acceptat.',['productnew','docseries','seriesbackfill','productsql'],['Identifică allocator, index/constraint și scope exact.','Rulează două cereri sincronizate în fixture; repetă la limita secvenței și cu retry după timeout.','Verifică conflict controlat sau rezultate distincte și absența lost update.'],['Identități distincte, fără dublură tăcută; retry este trasabil și nu creează articol suplimentar.'],['Same Value în același client; aceeași secvență din două procese; unicitate pe NULL; overflow.'],'Mesaj concurență recuperabil, fără succes fals.','Trace thread/transaction/correlation_id al celor două cereri.','SQL04/06 și snapshot alocări; scope unicitate documentat.','Utilizatorul poate relua fără a crea copie accidentală.','Verifică secvențe native separat de UUID și numerele documentelor fiscale.');
add(8,'Mapare cabinet–firmă deterministă','Aceeași firmă prezentă în mai multe cabinete se rezolvă exclusiv în cabinetul solicitant.',['clientmap'],['Reconstruiește contractul managing_uuid+tenant_cui și toate citirile/migrările conexe.','Folosește două cabinete cu același CUI și AD_Client diferit; migrează fixture legacy ambiguă.','Verifică eroare/blocaj explicit când probe-ul unui cabinet este indisponibil și reluarea controlată.'],['Nicio atribuire la ultimul importator; lipsa mapării nu devine listă contabilă goală aparent validă.'],['Host indisponibil; două rezultate AD_Client; CUI-only fallback; client inexistent.'],'Pagina contabilă indică firma corectă și eroare de mapare explicită.','Trace resolver și client_map_migration; nicio credențială în dovadă.','SELECT eva_idempiere_client_map/managed_firms numai după confirmarea schemelor și coloanelor.','Eroarea nu poate fi confundată cu firma fără activitate.','AD_Client și AD_OrgInfo/TaxID validate nativ; A01 deține izolarea.');
add(9,'Migrare fresh','Instalarea pe o bază curată produce schema și AD complete necesare fluxurilor declarate.',['activator','metadata','wmsmodel','coretables','fluxtables','productsql'],['Pornește fixture core suportată cu extensii în ordinea declarată.','Capturează baseline și diferență AD/fizic/index/proces/meniu.','Deschide formular/proces reprezentativ și persistă minimul prin API nativ în test.'],['Toate obiectele necesare prezente; niciun câmp obligatoriu fără default/valoare; bootstrap eșuat este vizibil.'],['AMN/2Pack întârziat; index eșuat; rol fără drepturi de setup; dependență plugin lipsă.'],'Formular funcțional după prima instalare.','Log complet bootstrap cu phase/result și manifest.','SQL02/03/04 și fingerprint schema fresh.','Nicio funcție disponibilă în meniu înainte de îndeplinirea prerechizitelor.','CreateTable/ColumnSync și EntityType verificate; metodele native folosite nu se presupun tranzacționale fără probă.');
add(10,'Upgrade fără pierderi','Upgrade-ul din fiecare schemă anterioară suportată păstrează datele și sensul lor.',['metadata','coretables','clientmap','legacyseriessql','fxsql'],['Stabilește explicit versiunile suportate și fixture reprezentative, inclusiv câmpuri retrase și date nule.','Execută migrarea oficială în test și reconciliază rânduri, identități, solduri și metadata.','Verifică vechi linkuri/documents și noile validări.'],['Nicio pierdere sau remapare tăcută; versiunea nesuportată refuzată cu remediere.'],['Coloane fizice retrase încă populate; duplicates care împiedică unique; backfill incomplet; moneda absentă.'],'Istoric vizibil și mesaj de migrare incompatibilă.','Journal al pașilor și verificări pre/post.','Checksums agregate și counts pe fixture; SQL02/03/04.','Utilizatorul înțelege dacă operația poate continua sau trebuie corectată.','AD upgrade vs native migration script compatibilitate demonstrată.');
add(11,'Reexecuție și întrerupere migrare','Reluarea unei migrări complete sau întrerupte converge la aceeași schemă și aceleași date.',['activator','metadata','wmsmodel','clientmap','seriesbackfill'],['Rulează fresh/upgrade de două ori în fixture.','Injectează întrerupere între metadata, creare fizică, index și backfill folosind mecanism test.','Reia procedura oficială și compară fingerprint/date; verifică două startup-uri concurente.'],['Fără dubluri de procese/meniuri/AD_Column/index/series; migrarea are rezultat final determinist.'],['Crash după AD_Column înainte de ColumnSync; index construit parțial; lock expiră; duplicat AD_Process.'],'UI rămâne coerentă după reluare și cache refresh.','Log faze și lock migrări, count created/existing verificat în DB.','Fingerprint schema/date + SQL02–06.','Indicator startup/setup și cale de recuperare explicite.','Idempotent din comentariu este ipoteză; se verifică MTable/MColumn și tranzacțiile efective.');
add(12,'Rollback și compatibilitate binar–schemă','Rollback-ul artefactului nu pornește peste o schemă incompatibilă fără barieră explicită.',['metadata','coretables','productsql','legacyseriessql'],['Documentează migrare expand/contract și versiune minimă de binar per schema.','În fixture verifică rollback la artefact anterior după migrare și după date noi.','Testează restaurare din snapshot când downgrade este nesuportat; reconciliază identități și evenimente.'],['Fie compatibilitate demonstrată, fie refuz sigur și runbook restore; fără pierdere acceptată tacit.'],['Coloană mandatory nouă; valoare enum nouă; coadă veche după rollback; registry extern cu ID mai nou.'],'Stare mentenanță explicită, fără ecran parțial funcțional.','Manifest versiuni și log refusal/rollback.','Snapshot fingerprint și reconciliere postrestore cu SQL readonly.','Operatorul are pași de recuperare verificați și estimare impact.','Compatibilitatea core/plugin/AD se verifică împreună cu A10.');
add(13,'Tranzacție atomică WMS','O operație WMS fie persistă toate efectele necesare, fie nu persistă niciun efect material parțial.',['wmsprocess','wmsstock','wmsmove','wmsevents'],['Desenează transaction boundary de la proces la PO/DB și observatori.','Injectează eroare după fiecare punct de persistare în fixture și compară stoc/jurnal/source.','Testează commit reușit cu răspuns pierdut și reluare pe aceeași instanță logică.'],['Fără stoc fără jurnal sau jurnal fără stoc; retry identifică efectul deja comis.'],['saveEx eșuează la ultima linie; log extern eșuează; nested trx=null; event postcommit întârziat.'],'Mesaj reflectă starea persistentă reală; refresh după timeout.','Trace transaction/correlation/source-document, nu doar processIt boolean.','SELECT EVA_StocWms/EVA_MiscareWms/AD_PInstance înainte/după.','Utilizatorul poate relua în siguranță fără a ghici succesul.','PO.saveEx/Trx și semantica event handler native confirmate.');
add(14,'Locking fără supraconsum','Concurența pe aceeași poziție/lot nu poate consuma mai mult decât cantitatea permisă.',['wmsstock','wmsprocess','reservation'],['Identifică ordinea lockurilor, cheia lock și izolarea efectivă.','În fixture două operații ambalează/pick-uiesc același disponibil; inversarea ordinii locatoarelor.','Colectează conflicte/timeout/deadlock și verifică retry limitat cu păstrarea sensului operației.'],['Cantitatea nu devine negativă fără politică explicită; un conflict nu lasă efecte parțiale.'],['Două procese în cabinete/firme distincte; aceeași cheie fără client; deadlock; lock pierdut la pool.'],'Mesaj de concurență cu actualizare cantitate disponibilă.','Timeline celor două tranzacții și mecanism lock.','SQL07 pe pg_locks/pg_stat_activity redactat în test; snapshots stoc.','Acțiunea blocată are timeout și cale de reluare, nu spinner permanent.','Lock PO/native storage comparat cu lock EVA; A05 validează oracle cantitativ.');
add(15,'Idempotency pe operație','Repetarea aceluiași eveniment logic are zero efect material nou, iar o operație nouă legitimă rămâne posibilă.',['wmsmodel','wmsstock','wmsmove','documents','fluxtables'],['Inventariază cheile de deduplicare pentru sursă/linie/operație/expediere și scope firmă.','Testează replay identic, payload diferit cu aceeași cheie, eveniment inversat și două expedieri ale unei comenzi.','Reconciliază stoc, cost, documente și jurnal.'],['Exact efectul așteptat per operație; conflict payload explicit; nu blochează livrare parțială legitimă.'],['Cheie numai order_id; Record_ID reutilizat între tabele; redelivery după restore; eveniment înaintea părintelui.'],'Istoric afișează replay/existent fără dublă finalizare.','Idempotency key/payload hash/transaction și rezultat persistent.','SQL04 plus SELECT sursă/linie/document și audit ledger.','Operatorul vede documentul existent și poate iniția operație nouă corect.','Native document link/reversal comparat înainte de mecanism nou.');
add(16,'Unicitate poziție și NULL/zero','Cheia de stoc identifică fără ambiguitate poziția, produsul, ASI și versiunea rețetei.',['wmsmodel','wmsstock','series','lots'],['Documentează semantica ASI/BOM zero versus NULL și normalizarea la citire/scriere.','Testează două inserări logic identice cu reprezentări NULL/0 în fixture și două versiuni BOM legitime.','Verifică scope client/locator și materializarea aceleiași chei în agregări.'],['Dublurile logice sunt respinse/unificate conform regulii; pozițiile distincte rămân distincte.'],['Unique permite multiple NULL; COALESCE diferit în query; lot diferit agregat prematur.'],'Pozițiile duplicate nu apar ca disponibil suplimentar.','Mapper/normalizator cheie și garda persistare.','SQL04/06 pe cheia declarată; selecție rânduri fixture.','Cod lot/serie/rețetă/locator vizibil în selecție.','MA/ASI native și convenția ID=0 se verifică în modelul core exact.');
add(17,'G1 contabil fără stoc duplicat','Aceeași cantitate fizică nu este contabilizată încă o dată prin reprezentarea G2/CPA/G3.',['wmsmirror','wmsprocess','inventorydoc','costengine'],['Definire bilanț cantitativ și valoric înainte/după recepție, ambalare, dezambalare, mutare, pick.','Compare M_StorageOnHand/M_Transaction/costuri/Fact_Acct cu registrul WMS și disponibilul G3.','Separă set cumpărat indivizibil CPP de CPA dezasamblabil și warehouse multiplu legitim.'],['Conservare pe componente și o singură recunoaștere contabilă; G3 nu adaugă stoc contabil.'],['MProduction folosit ca simplă ambalare; contabilizare G2; transfer net0 cu Fact_Acct nenul.'],'Aceeași marfă este prezentată ca perspective etichetate, fără total aditiv fals.','Handlers de reflectare și postare identificați.','Reconciliere M_StorageOnHand/M_Transaction/MCost* și Fact_Acct, pe tabel real verificat.','G1/G2/G3 și gestiunea contabilă sunt clare.','MProduction numai transformare contabilă reală; MMovement poate genera linii contabile, nu se presupune zero.');
add(18,'Multi-G1/G2 și referințe','Fiecare gestiune/locator/legătură WMS aparține contextului și cardinalității aprobate.',['wmsmodel','wmspair','wmsrelation','warehouseform','locatorform'],['Clarifică legătura permisă între G1.n și G2.n din cerințe și schema implementată, fără a impune automat 1:1.','Configurează minimum două G1 și două G2, inclusiv schimbare responsabil/locator inactiv.','Testează activare/mutare/dezactivare cu stoc și documente în lucru.'],['Cardinalitatea și conturile/locațiile corespund cerinței; fără mutare implicită sau orfani.'],['Aceeași G2 legată la alt G1; locator din alt warehouse; ștergere cu stoc; schimbare link în timpul pick.'],'Taburi și selectoare separate, filtrate, context vizibil.','Validare server Pereche/RegulaLegatura și proces activare.','FK/index candidat eva_perechewms_g_uk/w_uk verificat față de modelul aprobat.','Mufele de configurare previn combinații invalide și explică refuzul.','M_Warehouse/M_Locator native reutilizate; A05 confirmă modelul fizic.');
add(19,'Genealogie BOM versionată','Stocul asamblat păstrează rețeta și componentele efectiv folosite, indiferent de editarea ulterioară a rețetei.',['wmsbom','wmsnote','wmsprocess','wmsmodel'],['Creează două versiuni BOM cu data efectivă și UOM diferite; ambalează cu prima.','Schimbă definiția curentă apoi dezambalează/pick conform stocului istoric.','Verifică legăturile sursă→set→componente/lot și documentele de reversare.'],['Dezambalarea reconstruiește componentele reale; istoricul nu este recalculat după rețeta nouă.'],['BOM ciclic; cantitate0; versiune absentă; lot incompatibil; rounding UOM.'],'Dialog afișează versiunea și consecințele, nu doar denumirea setului.','Rezolvare BOM și lineage persistent în proces.','SELECT PP_Product_BOM/PP_Product_BOMLine dacă instalate, EVA_StocWms și jurnal.','Utilizatorul nu poate selecta o rețetă incompatibilă stocului.','Verifică plugin BOM instalat vs core, funcție reală și diferență EVA.');
add(20,'Ambalaje și manoperă o singură dată','Fiecare operație reală recunoaște consumul și costul o singură dată în G1.',['wmsprocess','wmsbom','costengine','costlayers','documents'],['Definire oracle cu A03/A05 pentru cutii, manoperă, ambalare/repack și dezasamblare.','Compară operație inițială, replay identic și repack nou cu ID nou; urmărește documentul de cost.','Reconciliază jurnal operații și Fact_Acct/cost fără stoc contabil suplimentar CPA.'],['Replay zero consum/cost nou; repack legitim are consumul real; manopera nu dublează cheltuiala salarială.'],['Cost înregistrat în G2 și G1; retry după commit; cutie recuperabilă vs nerecuperabilă; cost orfan.'],'UI separă operație, consum și cost și oferă documentele asociate.','Corelare operation_id→document consum/cost nativ.','SELECT document consum, cost și Fact_Acct cu reconciliere; niciun tabel presupus fără AD.','Operatorul distinge corecția/reversarea de o operație nouă.','Analiză native cost collector/issue/production aplicabile înainte de propuneri noi.');
add(21,'Inventar ASI/MA corect','Cantitatea inventariată urmărește loturile/seriile reale inclusiv când alocarea este în tabela MA.',['inventoryimport','inventoryprocess','inventorydoc','series','lots'],['Include inventar fără ASI, ASI explicit și linie ASI=0 cu MA validă.','Urmărește complete/reversal și reconciliază qty book/count/difference pe locator și lot.','Verifică același serial în două poziții și inventar parțial.'],['MA valid nu este defect; totalul detaliilor coincide cu efectul; fără serial duplicat material.'],['MA incomplet/duplicat; ASI de alt produs; serie deja livrată; barcode gol; delta negativă nepermisă.'],'Ecran inventar și detaliu lot/serie reflectă alocarea.','Trace MInventory/MInventoryLine/MA și handler fiscal.','SELECT M_InventoryLine, M_InventoryLineMA, M_Transaction, storage după confirmare schema.','Mesajul indică exact lotul/locatorul inconsistent și păstrează numărătoarea.','Compară core inventory/MA posting în versiunea instalată; fără regulă falsă ASI=0 invalid.');
add(22,'Rezervări o singură scădere','Disponibilul agregat scade fiecare rezervare o singură dată în domeniul ei real.',['reservation','documents','wmsstock'],['Fixture două G1 cu10+10 și rezervare globală7: oracle13; ulterior alocare warehouse/ASI.','Compare rezervare nativă și EVA pentru aceeași comandă și stări anulată/parțial livrată.','Rulează agregări pe warehouse și total fără duplicarea rezervării globale.'],['20−7=13 și atribuire coerentă; aceeași rezervare nativ/EVA nu este scăzută dublu.'],['Rezervare globală scăzută în fiecare warehouse→6; order join multiplică linii; expirare nepropagată.'],'Total canal și detaliu depozit concordă; disponibil în curs de recalcul afișat.','SQL_STOC/SQL_REZ_NATIVA/SQL_REZ_T22 și mapări sursă.','SELECT M_StorageReservation/EVA_ComandaSiteLinie/M_StorageOnHand după schema confirmată.','Utilizatorul vede motivul blocării și alocarea rezervării.','Semantica MStorageReservation native vs stări comenzi confirmată cu A06.');
add(23,'G3 alternative pe resurse comune','Combinațiile virtuale publicate consumă același buget de componente la rezervare.',['reservation','wmsbom','productmap','fluxtables'],['Fixture P1/P2/P3=120 fiecare, S1=6 fiecare și S2=3 fiecare.','Verifică ofertă20/40 ca alternative, apoi comenzi mixte concurente și conversia CPA→CPP.','Reconciliază după anulare/parțial/livrare și schimbare versiune rețetă.'],['Expunerea alternativelor nu creează stoc fizic; comanda mixtă nu depășește resursa comună.'],['20 S1 +40 S2 acceptate simultan; rezervare pe SKU independent; BOM cache vechi.'],'Catalog arată alternative coerent și refuz de disponibil explicabil.','Generator ATP/rezervare/mapare canal localizat după gate, inclusiv owner runtime.','SELECT bază componente, rezervări și mapare; total oracle calculat independent.','Nu se afișează total stoc aditiv al combinațiilor.','Compară BOM/ATP native și funcții EVA existente cu A05/A06/A08 înainte de extensie.');
add(24,'Dimensiuni fizice independente','Datele păstrează independent forma, calitatea, locația, tranzitul și angajamentul stocului.',['wmsmodel','wmsstock','wmsregister','reservation'],['Construiește matrice fixture: asamblat+carantină+locator+rezervat, component+tranzit etc.','Verifică modelul și queryurile de disponibil pentru fiecare axă.','Parcurge schimbarea unei axe și verifică celelalte nemodificate.'],['Nicio stare singulară nu șterge informația necesară; disponibilul exclude numai dimensiunile stabilite.'],['Transfer pierde rezervare; carantină devine disponibilă prin ambalare; pick șterge lotul.'],'Filtre independente și explicație stoc indisponibil.','Model/stări/transformări și DTO păstrează dimensiunile.','Inventar coloane/reference/enum și snapshots pe fiecare axă.','Etichete ușor de înțeles fără combinări imposibile.','Mapare ASI/locator/in-transit/reservation native evaluată în configurația reală.');
add(25,'DocStatus și postare separată','Starea documentului și efectele contabile sunt confirmate persistent, nu deduse dintr-un boolean de proces.',['documents','inventorydoc','inventoryprocess','period'],['Parcurge DR/IP/WP/WC/CO/VO/RE aplicabile, inclusiv aprobare și perioadă închisă.','Compară UI, DocAction/DocStatus, ProcessInfo, Posted/Processing și Fact_Acct.','Reia documentul existent după eroare/timeout fără a crea document înlocuitor implicit.'],['Succes operațional numai pentru starea acceptată; postarea are stare separată și reconciliere.'],['processIt=true dar WP; CO nepostat; fact invalid; periodclosed; reversalparțial.'],'Stare și mesaj concordante, cu link la document și pași următori.','Trace processIt + save/commit și cod rezultat real.','SELECT DocStatus/DocAction/Posted și Fact_Acct cu AD_Table_ID/Record_ID.','Utilizatorul înțelege așteptarea aprobării/postării și poate relua.','Native DocAction/DocumentEngine și process state machine sunt sursa oracle cu A03.');
add(26,'Jurnal audit integral','Orice modificare materială are autor, context, timp și legătură cu operația/documentul sursă.',['fluxtables','wmsmodel','wmsmove','coretables'],['Inventariază AD_ChangeLog, jurnal EVA, AD_PInstance și log proces; stabilește ce este acoperit de fiecare.','Creează/actualizează/reversează în fixture pe UI/API/job și urmărește schimbările inclusiv trigger.','Verifică retenția, accesul și protecția jurnalului; fără expunere chei/API/PII inutile.'],['Lanț corelabil end-to-end; append-only și excepțiile de administrare explicit documentate.'],['Job fără actor; delete fără urmă; jurnal înainte rollback; secrets în payload; timestamp fără timezone.'],'Istoric accesibil rolului autorizat cu referințe document.','Correlation/causation IDs și tip sursă materială.','SELECT metadata log și câmpuri redactate, SQL08 trigger inventory.','Istoricul explică ce s-a schimbat și de ce, nu numai ID tehnic.','AD_ChangeLog nu se presupune universal activ; verifică configurarea AD_Table/Column et al.');
add(27,'Trigger și efect implicit','Niciun trigger/rule/default/event observer material nu rămâne în afara modelului de efecte.',['activator','wmsevents','wmsvalidate','metadata'],['Inventariază pg_trigger/pg_rules/default/generated și listeners OSGi pentru tabelele deținute.','Leagă fiecare efect implicit de pipeline și ordinea tranzacțională.','Testează în fixture operația declanșatoare și eroarea/retry/reversal; compară rezultate cu modelul.'],['100% efecte implicite inventariate și titular desemnat; fără efect contabil/sync ascuns.'],['Trigger instalat manual absent repo; listener în două bundleuri; recursie; funcție security definer.'],'Rezultatul afișează efectele operației relevante pentru utilizator.','Lista event subscriptions și ordinea invocării.','SQL08 metadata trigger/rules; funcțiile se citesc ca text, nu se execută.','Erorile nu ascund suboperația eșuată.','Native validators/eventtopics/DocFactory și trigger core diferențiate de EVA.');
add(28,'Import master data reversibil logic','Importul păstrează identitățile și referințele fără a ocoli regulile native de persistare.',['sagaproduct','sagastock','sagainventory','sagasave','sagaregistry','sagapreflight'],['Stabilește provenance source-row→native-ID și politicile reimport/merge/quarantine.','În fixture importă duplicate, linii dependente lipsă și loturi; întrerupe/reia.','Compară cantități/solduri și ledgerimport; corecția se face prin mecanism autorizat, nu SQLbusiness.'],['Reimport stabil; fără mapare ambiguă CPP/CPA; erorile au sursă și acțiune.'],['Source key reciclat; produs șters/reactivat; cod ambiguu; partial batch; bypass PO.'],'Rezumat import cu total reușit/refuzat/omis și acces la motive.','Trace native REST/PO vs scrieri SQL și registry.','SELECT import mapping/staging și tabele native confirmate; reconcilieri A04.','Operatorul poate relua numai erorile fără duplicarea succeselor.','Funcțiile import native existente analizate înainte de propuneri noi; A04 are ownership flux.');
add(29,'Numere documente și secvențe','Alocarea numerelor respectă contextul serie/perioadă și nu produce dubluri sub concurență/retry.',['docseries','numberrange','seriessql','legacyseriessql','regseriessql','seriesbackfill'],['Inventariază AD_Sequence/C_DocType și toate registry portal/EVA; stabilește o sursă autoritativă per tip.','Testează cutoff, două firme, anul nou, range epuizat, anulare și rollback.','Verifică numărul fiscal separat de ID produs/UUID și politica pentru goluri justificabile.'],['Număr unic conform domeniului și politică documentată pentru anulare/gap; fără backfill rescriind documentul emis.'],['Scope numai prefix; cursă range; restore secvență veche; document draft primește definitiv duplicat.'],'Ecran serie arată interval/stare/firmă și refuz recuperabil.','Trace MSequence/SeriiDocumente și mapări legacy.','SQL04/06 plus SELECT AD_Sequence/C_DocType și EVA_SeriiPlaje dacă instalată.','Setări clare, fără termen cod intern folosit pentru numărul facturii.','Oracle fiscal validat A03 din surse actuale; A02 verifică mecanismul nativ.');
add(30,'Monedă, precizie și dată','Persistarea sumelor și datelor conservă regula contabilă aplicabilă documentului.',['fxsql','productmodels','costengine','period'],['Inventariază numeric precision/scale, monedă/curs/tipcurs, timestamp vs date, timezone.','Fixture monedă secundară, rotunjiri pe linie/total și perioadă la miezul nopții Europe/Bucharest/DST.','Reconciliază valoarea UI/API/DB/postare și registrul fiscal versionat.'],['Fără float monetar pierdut ori data contabilă deplasată; cursul folosit rămâne auditabil.'],['Curs lipsă;0; scară redusă; anulare cu alt curs; zonă UTC diferită; retroactiv după schimbare cotă.'],'Sume/monedă/data corect etichetate și eroare la curs lipsă.','Tipurile DTO și conversii/rounding localizate.','SELECT schema numeric/date și valori fixture; oracle A03.','Format local nu schimbă valoarea persistentă.','C_Currency/C_Conversion_Rate/precision native comparate cu registry EVA și politici A03.');
add(31,'Performanță interogări și indexuri','Interogările critice respectă bugetul acceptat la volume și distribuții reprezentative fără pierderea izolării.',['reservation','wmsstock','inventoryread','productrouter','portfolio'],['Fixează cu A10 SLA și fixture1k/100k/1m după capacitate; index/testplan pe tenant mare și skew.','Inspectează EXPLAIN fără ANALYZE în snapshot readonly; măsurători active numai în test.','Măsoară p50/p95/p99, blocaje, export/paginare și regresie cu concurență1/10/50.'],['Bugete măsurabile îndeplinite; missing SLA=NEEXECUTAT_CRITERIU, nu PASS; total/pagini stabile.'],['Offset mare; N+1; index pe tenant lipsește; filtrare client după paginare; rezervări cu join exploziv.'],'Loading/progress/cancel și limite de export fără blocaj.','Trace query count/latency și pool utilization cu A10.','SQL09 index size/stat; EXPLAIN documentat separat, fără query secret/PII.','Tastatura și filtrarea rămân utilizabile cu volume mari; empty≠timeout.','Indexuri native existente considerate înainte de adăugare; nu propune duplicate.');
add(32,'Cache și consistență citire','După commit/migrare/context switch, citirile prezintă datele și metadata versiunii corecte.',['metadata','wmsmodel','productservice','inventoryread','reservation'],['Inventariază cache local/distribuit/AD și invalidările efective.','Actualizează stoc/produs/schema în fixture și citește din a doua sesiune/nod.','Testează timeout invalidare și schimbare client/canal.'],['Fără stoc/catalog/AD vechi acceptat ca actual; izolarea cache include contextul necesar.'],['Cache key doar product_id; alt cabinet același ID; stoc revizie veche; restart doar un nod.'],'Indicator stale/refresh și verificare finală server la acțiune.','Trace CacheMgt/EVA_Revizie sau mecanism descoperit.','SELECT revizie/date committed comparate cu răspunsurile.','Utilizatorul nu finalizează pe cantitate cache fără reverificare.','Semantica CacheMgt native verificată; A09/A10 pentru cache UI/infrastructură.');
add(33,'Autoritate date portal–ERP','Fiecare câmp replicat are o sursă autoritativă și o regulă de reconciliere explicită.',['productsql','portfoliosql','productmodels','productservice','portfolio','producthtml'],['Construiește field matrix produs/preț/SKU/EAN/canal și owner ERP/portal/Spree.','Testează update/retry/conflict/sync absent pe ambele direcții autorizate în test.','Reconcilează schema DTO și persistența; identifică cod dormant vs deployed.'],['Cache nu devine master tăcut; conflictele nu suprascriu codul intern CPP/CPA.'],['sku_cache învechit; preț modificat simultan; portal vechi cu câmp nou; Spree DB nereprezentată în Git.'],'UI indică sursa/editabilitatea și status sync.','Contract versionat și mapper, ruta deploy confirmată A10.','SELECT eva_product_ext/variant/channel_map și M_Product/M_ProductPrice dacă instalate.','Utilizatorul știe unde modifică efectiv informația.','M_Product/M_ProductPrice/List native comparate; actual Spree repo/schema cerute separat.');
add(34,'Dublă verificare reutilizare nativă','Fiecare diferență recomandată este susținută de o verificare în cod nativ și una în instalarea reală.',['metadata','wmsprocess','inventorydoc','docseries','reservation'],['Pentru fiecare capabilitate inventariază core13/plugin/EVA/config și SHA/simbol candidat.','Verifică AD_Window/Process/Form/Menu/Roles/config și un scenariu în cabinetul test cu bundle identic.','Calculează gap funcțional, cost/risc și alternativa de configurare/adaptare înainte de dezvoltare nouă.'],['Nativ existent se reutilizează când acoperă obiectivul; absența are corpus delimitat, nu concluzie globală.'],['Clasă în source dar bundle neinstalat; proces instalat fără drepturi; funcție cu nume similar și alte efecte contabile.'],'Captură traseu meniu și parametri ai funcției native.','SHA core exact și cale/simbol/log scenariu.','AD/process/table config plus efecte pe tabele native verificate.','Se evită ferestre duplicate și se păstrează navigarea contabilă.','Obligatoriu două dovezi independente: source și installed behavior; lipsa oricăreia rămâne NEEXECUTAT.');
add(35,'Dovezi și acoperire închisă','Niciun control sau obiect DB in-scope nu este declarat verificat fără probă reproductibilă.',['metadata','wmsmodel','coretables','fluxtables'],['Leagă inventar↔control↔pipeline↔task A12↔evidence/finding↔A11.','Reconcilează numitor total cu PASS/FAIL/NEEXECUTAT/NA aprobat.','Un al doilea auditor reproduce eșantionul de risc și toate defectele critice; păstrează istoricul respins/corectat.'],['Acoperire exactă și limite vizibile; nota calității nu este confundată cu sănătatea produsului.'],['Test doar mock folosit drept ERP proof; fișier vechi la SHA nou; număr task fără capitol; SQL fără context.'],'Capturi navigabile și redactate ale scenariului real.','SHA/linie și comandă exactă cu expected/actual.','Hash snapshot/query/result și timestamp/context fără secrete.','Raport inteligibil: ce/cum/unde/când și efect asupra operatorului.','Afirmațiile native au cele două dovezi cerute de controlul34.');

