const sql=[
{id:'SQL01',purpose:'Identitate DB/versiune fără credențiale',query:'SELECT current_database() AS database_name, current_schema() AS schema_name, version() AS server_version;',prerequisites:'Conexiune autorizată numai citire; numele mediului redactat în livrarea publică.'},
{id:'SQL02',purpose:'Schema fizică și domenii de date',query:'SELECT table_schema, table_name, column_name, data_type, udt_name, character_maximum_length, numeric_precision, numeric_scale, is_nullable, column_default FROM information_schema.columns WHERE table_schema = :schema_name ORDER BY table_name, ordinal_position;',prerequisites:'Parametru schema din allowlist; metadate numai.'},
{id:'SQL03',purpose:'AD Dictionary separat de schema fizică',query:'SELECT t.ad_table_id, t.tablename, t.entitytype, t.isactive, c.ad_column_id, c.columnname, c.ad_reference_id, c.ad_reference_value_id, c.fieldlength, c.ismandatory, c.iskey, c.isactive AS column_active FROM ad_table t LEFT JOIN ad_column c ON c.ad_table_id=t.ad_table_id WHERE lower(t.tablename) = ANY(:table_names) ORDER BY t.tablename,c.columnname;',prerequisites:'Confirmă coloanele din SQL02 înainte; lista tabelor fixată din manifest, fără date business.'},
{id:'SQL04',purpose:'PK/FK/unique/check și validare/deferabilitate',query:'SELECT n.nspname AS schema_name, c.relname AS table_name, x.conname, x.contype, x.convalidated, x.condeferrable, x.condeferred, pg_get_constraintdef(x.oid) AS definition FROM pg_constraint x JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=:schema_name ORDER BY c.relname,x.conname;',prerequisites:'Funcție PostgreSQL de metadate read-only; nicio funcție business executată.'},
{id:'SQL05',purpose:'Referințe warehouse/locator în afara contextului, pe fixture autorizată',query:'SELECT l.m_locator_id, l.ad_client_id AS locator_client, w.ad_client_id AS warehouse_client FROM m_locator l LEFT JOIN m_warehouse w ON w.m_warehouse_id=l.m_warehouse_id WHERE l.ad_client_id=:client_id AND (w.m_warehouse_id IS NULL OR w.ad_client_id<>l.ad_client_id);',prerequisites:'AD/schema confirmate; include excepțiile sistem numai dacă politica nativă le permite și A01 validează.'},
{id:'SQL06',purpose:'Dubluri logice stoc EVA inclusiv NULL/0',query:'SELECT ad_client_id,m_locator_id,m_product_id,COALESCE(m_attributesetinstance_id,0) AS asi,COALESCE(pp_product_bom_id,0) AS bom,COUNT(*) AS rows_count FROM eva_stocwms WHERE ad_client_id=:client_id GROUP BY ad_client_id,m_locator_id,m_product_id,COALESCE(m_attributesetinstance_id,0),COALESCE(pp_product_bom_id,0) HAVING COUNT(*)>1;',prerequisites:'Execută doar dacă ModelWms și schema confirmă semantica NULL/0; altfel adaptează explicit queryul înaintea probei.'},
{id:'SQL07',purpose:'Blocaje sesiuni de test',query:'SELECT l.pid,l.locktype,l.mode,l.granted,a.state,a.wait_event_type,a.wait_event FROM pg_locks l LEFT JOIN pg_stat_activity a ON a.pid=l.pid WHERE a.datname=current_database() AND a.application_name=:audit_application_name ORDER BY l.pid,l.locktype;',prerequisites:'Numai fixture și application_name distinct; fără text query/PID alte sesiuni în raport.'},
{id:'SQL08',purpose:'Inventar trigger/rule implicit',query:'SELECT n.nspname,c.relname,t.tgname,t.tgenabled,t.tgisinternal,pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=:schema_name ORDER BY c.relname,t.tgname;',prerequisites:'Definiții citite ca text; nu se invocă trigger/function. Complement SELECT schemaname,tablename,rulename,definition FROM pg_rules WHERE schemaname=:schema_name.'},
{id:'SQL09',purpose:'Indexuri și statistici',query:'SELECT s.schemaname,s.relname,s.indexrelname,s.idx_scan,s.idx_tup_read,s.idx_tup_fetch,pg_relation_size(s.indexrelid) AS index_bytes FROM pg_stat_user_indexes s WHERE s.schemaname=:schema_name ORDER BY s.relname,s.indexrelname;',prerequisites:'Statisticile pot fi resetate; baseline și timestamp obligatorii. Planul query se obține cu EXPLAIN separat doar după autorizare; fără ANALYZE în producție.'},
{id:'SQL10',purpose:'Efect contabil asociat unui document fixture',query:'SELECT ad_table_id,record_id,c_acctschema_id,account_id,c_currency_id,SUM(amtacctdr) AS debit,SUM(amtacctcr) AS credit,COUNT(*) AS rows_count FROM fact_acct WHERE ad_client_id=:client_id AND ad_table_id=:table_id AND record_id=:record_id GROUP BY ad_table_id,record_id,c_acctschema_id,account_id,c_currency_id ORDER BY c_acctschema_id,account_id;',prerequisites:'Schema confirmată; oracle A03 și document autorizat. SUM debit=credit nu probează singur corectitudinea conturilor sau absența dublării.'},
{id:'SQL11',purpose:'Schema index real valid/ready plus definiție',query:'SELECT n.nspname,c.relname AS table_name,i.relname AS index_name,x.indisunique,x.indisvalid,x.indisready,pg_get_indexdef(i.oid) AS definition FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class c ON c.oid=x.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=:schema_name ORDER BY c.relname,i.relname;',prerequisites:'Index existent dar invalid nu devine protecție dovedită.'}
].map(q=>({...q,status:'NEEXECUTAT',execution_policy:'PLAN ONLY; parametrizare driver, timeout/rowlimit; cont DB read-only; fără concatenare input, DML/DDL/CALL/funcții business/SELECT FOR UPDATE în producție.'}));

