    /** Corpul scrierii pe un depozit dat; întoarce numărul mișcărilor scrise. Refuzurile ⇒ {@link AdempiereException} tradusă. */
    public static int aplica(Depozit d, int client, List<MiscareWms> miscari) {
        if (client <= 0)
            throw new IllegalArgumentException("AD_Client_ID " + client);
        Map<Integer, MiscareWms.ContextValidare> ctxW = new LinkedHashMap<>();
        for (MiscareWms m : miscari) {
            MiscareWms.ContextValidare c = m == null || m.gestiuneWms() <= 0 ? null : ctxW.computeIfAbsent(m.gestiuneWms(),
