            d.lacat(k);
        for (MiscareWms m : miscari) {
            if (m.doarLipsa()) {   // 20_ C-5: doar lipsa (W n-a acoperit nimic) — rândul de jurnal, stocul neatins
                d.scrieMiscare(client, m);
